base=[r[:] for r in grid]
for r,row in enumerate(grid):
    a=[c for c,v in enumerate(row) if v==4]
    for x,y in zip(a,a[1:]):
        for c in range(x+1,y): base[r][c]=2
for c in range(19):
    a=[r for r in range(10) if grid[r][c]==4]
    for x,y in zip(a,a[1:]):
        for r in range(x+1,y): base[r][c]=2
# iterative fill background cells that sit at endpoint of horizontal/vertical connected 4/2 runs (one adjacent cell in each axis)
out=[r[:] for r in base]
changes=[]
for r in range(10):
 for c in range(19):
  if grid[r][c]!=9: continue
  h=any(0<=c+dc<19 and out[r][c+dc] in (2,4) for dc in (-1,1))
  v=any(0<=r+dr<10 and out[r+dr][c] in (2,4) for dr in (-1,1))
  if h and v:
   changes.append((r,c)); out[r][c]=2
print(changes)
print('\n'.join(' '.join(map(str,r)) for r in out))

aug=[r[:] for r in base]
# collect horizontal and vertical marker spans
hsp=[]
for r,row in enumerate(grid):
 cs=[c for c,v in enumerate(row) if v==4]
 if len(cs)>=2: hsp.append((r,min(cs),max(cs)))
vsp=[]
for c in range(19):
 rs=[r for r in range(10) if grid[r][c]==4]
 if len(rs)>=2: vsp.append((c,min(rs),max(rs)))
# Connect a line segment to any perpendicular segment when their intersection lies on one segment but outside the other.
for r,lo,hi in hsp:
 for c,rlo,rhi in vsp:
  if lo<=c<=hi and not (rlo<=r<=rhi):
   for rr in range(min(r,rlo if r<rlo else rhi), max(r,rlo if r<rlo else rhi)+1):
    if grid[rr][c]==9: aug[rr][c]=2
  elif rlo<=r<=rhi and not (lo<=c<=hi):
   # not needed when intersection lies along vertical, connect horizontally to nearest horizontal endpoint
   cc=lo if c<lo else hi
   for x in range(min(c,cc),max(c,cc)+1):
    if grid[r][x]==9: aug[r][x]=2
print(hsp, vsp)
print('\n'.join(' '.join(map(str,r)) for r in aug))

